style.css:
@-moz-document domain("fuv.instructure.com") {
/* ===== 1) Global palette via CSS variables ===== */
:root {
  --ic-brand-primary: #2F80E4;                  /* Bleu de France */
  --ic-brand-primary-darkened-5:  #2973CC;
  --ic-brand-primary-darkened-10: #2366B5;
  --ic-brand-primary-darkened-15: #1D599E;

  --ic-brand-primary-lightened-5:  #4390E7;
  --ic-brand-primary-lightened-10: #5A9EEA;
  --ic-brand-primary-lightened-15: #6DA0E1;     /* Little Boy Blue */

  --ic-link-color: #5B61B2;                     /* Liberty */
  --ic-link-color-darkened-10: #4C5299;
  --ic-link-color-lightened-10: #7077C2;

  --ic-brand-font-color-dark: #2F2F2F;          /* Neutral dark for text */
  --ic-brand-font-color-dark-lightened-15: #555;
  --ic-brand-font-color-dark-lightened-28: #777;

  --ic-brand-global-nav-bgd: #5B61B2;           /* Liberty */
  --ic-brand-global-nav-ic-icon-svg-fill: #FFFFFF;
  --ic-brand-global-nav-ic-icon-svg-fill--active: var(--ic-brand-primary);
  --ic-brand-global-nav-menu-item__text-color: #FFFFFF;
  --ic-brand-global-nav-menu-item__text-color--active: var(--ic-link-color);

  --ic-brand-global-nav-menu-item__badge-bgd: #DEC1DB; /* Thistle */
  --ic-brand-global-nav-menu-item__badge-bgd--active: #2F80E4;
  --ic-brand-global-nav-menu-item__badge-text: #2F2F2F;
  --ic-brand-global-nav-menu-item__badge-text--active: #FFFFFF;

  --ic-brand-button--primary-bgd: var(--ic-brand-primary);
  --ic-brand-button--primary-text: #FFFFFF;
  --ic-brand-button--secondary-bgd: #5B61B2;    /* Liberty */
  --ic-brand-button--secondary-text: #FFFFFF;

  --ic-brand-Login-body-bgd-color: #EEE2DF;     /* Platinum */
  --ic-brand-Login-body-bgd-shadow-color: #C9B6B3;
}

/* ===== 2) Buttons ===== */
.ic-Button--primary {
  background-color: var(--ic-brand-primary) !important;
  color: #fff !important;
}
.ic-Button--primary:hover {
  background-color: var(--ic-brand-primary-darkened-10) !important;
}

/* ===== 3) Dashboard Cards ===== */
#DashboardCard_Container {
  background: transparent !important;
}
.ic-DashboardCard__box__container {
  background-color: inherit !important; /* keep Canvas course colors */
  border-radius: 12px !important;
  box-shadow: 0 2px 10px rgba(0,0,0,.08) !important;
}

/* ===== 4) Navigation Sidebar ===== */
.ic-app-header__logomark-container,
.ic-app-header__main-navigation {
  background: var(--ic-brand-global-nav-bgd) !important; /* Liberty */
}
.ic-app-header__menu-list-link {
  color: #fff !important;
}
.ic-app-header__menu-list-link:hover {
  color: var(--ic-brand-primary-lightened-10) !important;
}

/* ===== 5) To-Do Panel ===== */
#right-side {
  background: #fff !important;
  border-radius: 12px !important;
  box-shadow: 0 2px 12px rgba(0,0,0,.08) !important;
  border: 1px solid rgba(91,97,178,.15) !important; /* Liberty tint */
}
#right-side h2, #right-side h3 {
  color: var(--ic-brand-font-color-dark) !important;
  border-bottom: 2px solid var(--ic-brand-primary-lightened-15) !important; /* Little Boy Blue */
}
#right-side .to-do-list a {
  color: var(--ic-link-color) !important; /* Liberty */
}
#right-side .to-do-list a:hover {
  color: var(--ic-brand-primary) !important; /* Bleu de France */
}
#right-side .to-do-list li {
  background: rgba(222,193,219,.25) !important; /* Thistle tint */
  border-radius: 8px !important;
}

/* ===== 6) Alerts ===== */
.ic-flash-success, .ic-notification.success {
  background: rgba(47,128,228,.15) !important; /* Bleu de France tint */
  border-left: 4px solid var(--ic-brand-primary) !important;
}
.ic-flash-warning, .ic-notification.warning {
  background: rgba(222,193,219,.25) !important; /* Thistle tint */
  border-left: 4px solid #DEC1DB !important;
}
/* ========= Assignments (course > Assignments) ========= */
/* Section headers (Upcoming, Undated, Past…) */
#assignments .assignment-group .ig-header,
body.assignments .assignment-group .ig-header {
  background: #EEE2DF !important;                         /* Platinum */
  color: var(--ic-brand-font-color-dark) !important;
  border-left: 4px solid #2F80E4 !important;               /* Bleu de France */
  border-bottom: 1px solid rgba(91,97,178,.20) !important; /* Liberty tint */
  border-radius: 10px !important;
  padding: 8px 12px !important;
}

/* Assignment titles */
#assignments .ig-row .title a,
body.assignments .ig-row .title a {
  color: #5B61B2 !important;               /* Liberty */
  text-decoration: none !important;
  font-weight: 600 !important;
}
#assignments .ig-row .title a:hover {
  color: #2F80E4 !important;               /* Bleu de France */
  text-decoration: underline !important;
}

/* Meta (due date, points) */
#assignments .ig-details,
body.assignments .ig-details {
  color: #1D599E !important;               /* darkened primary */
  font-size: .9rem !important;
}

/* Pills / badges (e.g., New, Late) */
#assignments .badge,
#assignments .pill {
  background: #DEC1DB !important;          /* Thistle */
  color: #2F2F2F !important;
  border-radius: 999px !important;
}

/* Item separators */
#assignments .ig-row {
  border-top: 1px dashed rgba(91,97,178,.20) !important;   /* Liberty tint */
}

/* Publish icons */
#assignments .ig-published,
#assignments .publish-icon.published {
  color: #2F80E4 !important;               /* Bleu de France */
}


/* ========= Modules (course > Modules) ========= */
#context_modules .context_module,
#context_modules .ig-list {
  background: #fff !important;
  border: 1px solid rgba(91,97,178,.20) !important;        /* Liberty tint */
  border-radius: 12px !important;
  box-shadow: 0 2px 10px rgba(0,0,0,.06) !important;
}

/* Module headers */
#context_modules .ig-header,
#context_modules .context_module .name,
#context_modules .ig-title {
  background: #EEE2DF !important;          /* Platinum */
  color: var(--ic-brand-font-color-dark) !important;
  border-left: 4px solid #2F80E4 !important; /* Bleu de France */
  border-bottom: 1px solid rgba(91,97,178,.20) !important;
  border-radius: 10px 10px 0 0 !important;
  padding: 8px 12px !important;
}

/* Module item rows */
#context_modules .context_module_item,
#context_modules .ig-row {
  border-top: 1px dashed rgba(91,97,178,.20) !important;
}

/* Module item links */
#context_modules .ig-row .title a {
  color: #5B61B2 !important;               /* Liberty */
  text-decoration: none !important;
  font-weight: 600 !important;
}
#context_modules .ig-row .title a:hover {
  color: #2F80E4 !important;               /* Bleu de France */
  text-decoration: underline !important;
}

/* Publish state in Modules */
#context_modules .publish-icon.published,
#context_modules .ig-published {
  color: #2F80E4 !important;               /* Bleu de France */
}

/* Status/label chips inside modules */
#context_modules .badge,
#context_modules .pill {
  background: #DEC1DB !important;          /* Thistle */
  color: #2F2F2F !important;
  border-radius: 999px !important;
}
}
